    },
    [42] = {
      beijing = 0,
      dialog = 3,
      music = "96_2022Halloween",
      renwu = "npc",
      sentence = "My other senses seemed cut off in the memory. I felt no pain, but the sight still made me want to vomit. I ran with all my might to the edge.",
