    [43] = {
      beijing = 0,
      dialog = 3,
      music = "96_2022Halloween",
      renwu = "npc",
      sentence = "I ran for who knows how long, and I still hadn't reached the edge of the blood pool. My legs had melted away to bone; and, having lost the power to stand, I toppled over in despair.",
