    },
    [44] = {
      beijing = 0,
      dialog = 3,
      music = "96_2022Halloween",
      renwu = "npc",
      sentence = "But a green mist from the depths of the blood pool encircled me. The venomites scurried away in panic, as if trying to escape my vicinity.",
